export const EXAM_APLICAR = [{"id": 1, "q": "¿Qué es una computadora?", "opts": ["Un aparato utilizado para escuchar música", "Un dispositivo periférico", "Un dispositivo de almacenamiento", "Un dispositivo electrónico que interpreta y ejecuta comandos programados para operaciones de entrada y salida de datos, de cómputo y lógicas"], "correctText": "Un dispositivo electrónico que interpreta y ejecuta comandos programados para operaciones de entrada y salida de datos, de cómputo y lógicas"}, {"id": 2, "q": "¿Cuáles son las funciones fundamentales de un sistema de computación?", "opts": ["Procesamiento y almacenamiento", "Entrada de datos y almacenamiento", "Entrada de datos, procesamiento, almacenamiento y salida de datos", "Salida de datos y entrada de datos"], "correctText": "Entrada de datos, procesamiento, almacenamiento y salida de datos"}, {"id": 3, "q": "Son medios de almacenamiento:", "opts": ["Diskette, Disco Duro, Unidad de DVD.", "Diskette, Scaner, Disco Duro.", "Unidad de DVD, Carpetas.", "Disco Duro, Memoria, Cámara Digital."], "correctText": "Diskette, Disco Duro, Unidad de DVD."}, {"id": 4, "q": "¿Qué entiende por Hardware?", "opts": ["Partes de la computadora que ves y no puedes tocar.", "Partes Tangibles de una computadora.", "Componentes ideológicos de una computadora.", "Las actividades que realiza una computadora."], "correctText": "Partes Tangibles de una computadora."}, {"id": 5, "q": "¿Qué entiende por Software?", "opts": ["La base que sostiene a la Computadora.", "Los cables y los tornillos.", "Programas para el funcionamiento de la Computadora.", "Las partes físicas que conforman la Computadora."], "correctText": "Programas para el funcionamiento de la Computadora."}, {"id": 6, "q": "¿Qué es un Lenguaje de Programación?", "opts": ["Los que prenden y apagan la Computadora.", "La Unidad de DVD de la Computadora.", "Los fierros de la Computadora.", "Los que permiten que se le diga a la Computadora que hacer."], "correctText": "Los que permiten que se le diga a la Computadora que hacer."}, {"id": 7, "q": "¿Qué necesita un Software para poder ser instalado y utilizado por un usuario?", "opts": ["Que este lo suficientemente grande.", "Que no tenga faltas de ortografía.", "Que cuente con su Licencia.", "Que lo usen dos o más personas."], "correctText": "Que cuente con su Licencia."}, {"id": 8, "q": "¿Cómo se mide la velocidad de un procesador?", "opts": ["En horas", "En minutos", "En Gigaherzios (GHz) o Megaherzios (MHz)", "En GB"], "correctText": "En Gigaherzios (GHz) o Megaherzios (MHz)"}, {"id": 9, "q": "Programa que actúa como intermediario entre el usuario y el Hardware de un computador y su propósito es que el usuario pueda ejecutar programas:", "opts": ["Sistema Aplicativo.", "Programa operador.", "Sistema Operativo.", "Programa Objeto."], "correctText": "Sistema Operativo."}, {"id": 10, "q": "Es un lenguaje que puede ser utilizado para controlar el comportamiento de una Máquina, particularmente una computadora:", "opts": ["Lenguaje numérico", "Lenguaje de control", "Lenguaje de programación", "Lenguaje binario"], "correctText": "Lenguaje de programación"}, {"id": 11, "q": "¿Por qué es importante el mantenimiento preventivo de las computadoras?", "opts": ["Para que estén a la moda", "Para que sean poderosas", "Para el buen y adecuado funcionamiento del equipo.", "Porque lo tengo que hacer"], "correctText": "Para el buen y adecuado funcionamiento del equipo."}, {"id": 12, "q": "¿Qué es el mantenimiento preventivo para las computadoras?", "opts": ["Es el cuidado que se le da a las computadoras para prevenir posibles fallas", "Es un curso", "Es el mantenimiento de los carros", "Es usar bien los accesorios"], "correctText": "Es el cuidado que se le da a las computadoras para prevenir posibles fallas"}, {"id": 13, "q": "¿Por qué es importante conocer las partes que quitamos de la computadora?", "opts": ["Para ver que pasa", "Para saber qué función tiene y en qué lugar van conectadas.", "Para saber clasificarlas", "Para ver cuál es la parte más cara"], "correctText": "Para saber qué función tiene y en qué lugar van conectadas."}, {"id": 14, "q": "¿Por qué es importante revisar los conectores de una computadora a la hora de armarla?", "opts": ["Para que se vean bien", "Para saber que ahí van", "Para evitar falsos contactos", "Para clasificar los conectores"], "correctText": "Para evitar falsos contactos"}, {"id": 15, "q": "¿Se puede destapar el disco duro?", "opts": ["No", "Sí", "No sé", "Tal vez"], "correctText": "No"}, {"id": 16, "q": "¿Qué es el mantenimiento Correctivo?", "opts": ["Es el que está orientado al diagnóstico y reparación del equipo", "Es el modo de pruebas", "Es el que está orientado a ver cómo está el sistema", "Es que detecta errores de Software"], "correctText": "Es el que está orientado al diagnóstico y reparación del equipo"}, {"id": 17, "q": "¿Qué es la configuración de drivers periféricos?", "opts": ["Es la instalación de los programas para ser reconocidos los componentes", "Es la instalación de drivers", "Es la instalación de memoria dentro del CPU", "Es saber reorganizar la información en el disco duro"], "correctText": "Es la instalación de los programas para ser reconocidos los componentes"}, {"id": 18, "q": "¿Qué es la actualización del BIOS?", "opts": ["Es proveer a la máquina del Software indicado para el Mother Board", "Es darle a conocer la memoria RAM", "Es darle a conocer los parámetros a los discos duros", "Es la ruta de acceso para la instalación de Hardware"], "correctText": "Es proveer a la máquina del Software indicado para el Mother Board"}, {"id": 19, "q": "¿Para qué nos sirve un Antivirus?", "opts": ["Para eliminar o dejar sin efecto la acción de un Virus", "Para cargar la paquetería de Inicio", "Para Ahorrar espacio", "Para Cerrar aplicaciones"], "correctText": "Para eliminar o dejar sin efecto la acción de un Virus"}, {"id": 20, "q": "¿Cuál es la función de los driver de un dispositivo?", "opts": ["Cargarlos y permitir el funcionamiento del dispositivo", "Cargarlos y ahorrar espacio en el disco", "Cargarlos dentro del dispositivo", "Cargarlos para reducir espacio en la computadora"], "correctText": "Cargarlos y permitir el funcionamiento del dispositivo"}, {"id": 21, "q": "¿Qué es particionar el disco duro?", "opts": ["Dividirlo en pequeñas partes", "Dividirlo en partículas", "Dividirlo en varias unidades", "Dividirlo para su mejor acomodo"], "correctText": "Dividirlo en varias unidades"}, {"id": 22, "q": "¿Cómo se puede definir el mantenimiento preventivo en una rutina útil?", "opts": ["Como el conjunto de acciones y tareas periódicas que se realizan a un ordenador para optimizar su funcionamiento.", "Como el conjunto de acciones y tareas periódicas que se realizan a un ordenador para no optimizar su funcionamiento.", "Como el conjunto de actividades que no tienen alguna importancia en el funcionamiento del equipo de cómputo.", "Como rutinas inadecuadas."], "correctText": "Como el conjunto de acciones y tareas periódicas que se realizan a un ordenador para optimizar su funcionamiento."}, {"id": 23, "q": "¿Qué significa crear una imagen del disco duro?", "opts": ["Pérdida de espacio en disco duro.", "Pérdida de información.", "Crear una copia exacta de los datos que contiene el disco duro.", "Tomarle una foto con cámara digital."], "correctText": "Crear una copia exacta de los datos que contiene el disco duro."}, {"id": 24, "q": "¿Cuáles son los principales enemigos de las computadoras?", "opts": ["El sol y el viento", "El calor y la humedad", "El frío y la lluvia", "Los juegos y los programas"], "correctText": "El calor y la humedad"}, {"id": 25, "q": "Una medida de higiene para mantener limpio el teclado es:", "opts": ["No comer ni beber sobre el teclado", "No leer sobre el teclado", "No apoyar hojas sobre el teclado", "No utilizar el block de números"], "correctText": "No comer ni beber sobre el teclado"}, {"id": 26, "q": "¿Qué es una Red?", "opts": ["Dos o más equipos instalados en el mismo escritorio.", "Equipos interconectados entre sí.", "Conjunto de dispositivos, conexiones físicas y programas informáticos empleados para conectar dos o más computadoras.", "Equipos que comparten un mismo cable."], "correctText": "Conjunto de dispositivos, conexiones físicas y programas informáticos empleados para conectar dos o más computadoras."}, {"id": 27, "q": "¿Qué significan las siglas LAN?", "opts": ["Red", "La altura en la que se debe instalar un nodo.", "Red de área Local.", "El largo y ancho del nodo."], "correctText": "Red de área Local."}, {"id": 28, "q": "¿Cuál es la red que permite comunicación a través de grandes distancias?", "opts": ["Red de Área Extensa.", "Red de Área Local.", "Red de Área Metropolitana.", "Las 3 anteriores."], "correctText": "Red de Área Extensa."}, {"id": 29, "q": "¿Qué es un dispositivo de Red?", "opts": ["El de estrella, la jerárquica, la de bus.", "La Red de Área Local", "La PC, el Lector Óptico.", "Todo aquello que conecta entre sí a los dispositivos posibilitando su intercomunicación."], "correctText": "Todo aquello que conecta entre sí a los dispositivos posibilitando su intercomunicación."}, {"id": 30, "q": "¿Qué transporta un dispositivo de RED?", "opts": ["Luz.", "Datos.", "Sonidos", "Pixeles."], "correctText": "Datos."}, {"id": 31, "q": "¿Quién es responsable de crear y mantener tablas de ruteo por cada capa de protocolo de Red, así como seleccionar la mejor ruta basándose sobre diversos factores?", "opts": ["El cable de Red.", "El Rack.", "El Ruteador.", "La tierra física."], "correctText": "El Ruteador."}, {"id": 32, "q": "Dispositivo que permite centralizar el cableado de una Red y poder ampliarla:", "opts": ["Concentrador o Hub.", "Las canaletas.", "El Rack de Comunicaciones.", "El cable UTP."], "correctText": "Concentrador o Hub."}, {"id": 33, "q": "Es usado en algún punto de una Red informática donde todos los cables de Red terminan y donde se ubican los puertos de una Red:", "opts": ["El Jack", "El Nodo", "El Patch Panel.", "El Patch Cord."], "correctText": "El Patch Panel."}, {"id": 34, "q": "¿Cuál es el Protocolo de Red más popular del Mundo?", "opts": ["El dispositivo de Red.", "El Protocolo de Internet IP", "La dirección Mac.", "El dominio del equipo."], "correctText": "El Protocolo de Internet IP"}, {"id": 35, "q": "Protocolo de transferencia de Hipertexto usado en cada transferencia de la Red:", "opts": ["El protocolo de Control de Transporte.", "El HTTP (Hypertext Transfer Protocol)", "El Protocolo de Internet IP.", "El DHCP (Dynamic Host Configuration Protocol)."], "correctText": "El HTTP (Hypertext Transfer Protocol)"}, {"id": 36, "q": "Es un protocolo de transferencia de archivos entre sistemas conectados a una Red TCP basado en la arquitectura Cliente Servidor:", "opts": ["FTP (File Transfer Protocol).", "El WWW.", "El Google.", "El Switch."], "correctText": "FTP (File Transfer Protocol)."}, {"id": 37, "q": "Longitud máxima definida para un enlace horizontal para UTP:", "opts": ["100 mts", "3 mts", "90 mts", "60 mts"], "correctText": "90 mts"}, {"id": 38, "q": "Cable constituido por fibras de vidrio protegidas con recubrimientos plásticos. Algunas veces se incluyen alambres metálicos como elementos para dar resistencia mecánica.", "opts": ["Coaxial", "Fibra Óptica", "UTP", "Todos Los Anteriores"], "correctText": "Fibra Óptica"}, {"id": 39, "q": "Topología en la cual cada salida/conector de telecomunicaciones es cableado directamente al dispositivo de distribución.", "opts": ["Subsistema", "Estrella", "Terminal", "Jack"], "correctText": "Estrella"}, {"id": 40, "q": "Es un conjunto de elementos físicos que permiten la comunicación de voz, datos y video entre diferentes dispositivos:", "opts": ["NEXT", "Cableado Estructurado", "DELAY SKEW", "Subsistema"], "correctText": "Cableado Estructurado"}, {"id": 41, "q": "Dentro de la red Estructurada, los edificios y terrenos de un complejo, por ejemplo una universidad, colegio, parque industrial o instalación militar se conocen como:", "opts": ["Canal", "Campus", "Distribución principal", "Terminal"], "correctText": "Campus"}, {"id": 42, "q": "¿Para qué sirve el antivirus en los equipos cliente?", "opts": ["Para evitar la activación de virus", "Para detectar correo spam en la bandeja de Outlook", "Para detectar vulnerabilidades", "A y B"], "correctText": "Para evitar la activación de virus"}, {"id": 43, "q": "¿Qué es un virus de computadora?", "opts": ["Es un programa que se adjunta sólo a los archivos de sistema", "Es un software que se auto ejecuta y adjunta su código a otros archivos", "Es un programa que tiene por objeto alterar el funcionamiento de los archivos ejecutables.", "Es un software que reemplaza archivos de office."], "correctText": "Es un software que se auto ejecuta y adjunta su código a otros archivos"}, {"id": 44, "q": "¿Qué es una vulnerabilidad del sistema operativo?", "opts": ["Son huecos de seguridad que tienen los antivirus", "Son programas que permiten identificar las contraseñas del equipo.", "Son fallas en el diseño de los sistemas operativos que pueden comprometer la información de los equipos.", "A y B"], "correctText": "Son fallas en el diseño de los sistemas operativos que pueden comprometer la información de los equipos."}, {"id": 45, "q": "Medios más comunes de contaminación de un equipo de cómputo:", "opts": ["Instalación del Adware.", "Memorias USB.", "Programas gratuitos bajados de Internet.", "La opción B y C."], "correctText": "La opción B y C."}, {"id": 46, "q": "¿En dónde se programa que las actualizaciones se realicen de forma automática?", "opts": ["Inicio, Conectarse a:", "Inicio, botón derecho, escritorio.", "Inicio, Programas determinados.", "Inicio, Panel de Control."], "correctText": "Inicio, Panel de Control."}, {"id": 47, "q": "Cuando en una organización se tiene una red de computadoras, las máquinas que la integran pueden ser miembros de:", "opts": ["Una red social en Internet", "Un grupo de trabajo o un dominio", "Un grupo de trabajo y un dominio", "Un club de computadoras"], "correctText": "Un grupo de trabajo o un dominio"}, {"id": 48, "q": "A una computadora perteneciente a la red, previo a su migración a dominio en el Instituto, se le puede asignar cualquier nombre para su fácil identificación:", "opts": ["Dejarla sin nombre y permitir que el dominio le asigne uno.", "Cierto", "Falso. Debe cumplir con la Normatividad que al respecto ha definido Informática de Nivel Central", "De preferencia que se le asignen 2 nombres, para una mayor velocidad de acceso"], "correctText": "Falso. Debe cumplir con la Normatividad que al respecto ha definido Informática de Nivel Central"}, {"id": 49, "q": "Los 5 nombres de dominio definidos para la organización del Instituto son:", "opts": ["SAI, PREI, SIAP, SIAREFI, SIF", "México, Monterrey, Guadalajara, Yucatán", "Afiliación, Prestaciones Sociales, Informática, Prestaciones Económicas", "METRO, CTO, NTE, SUR, OCC"], "correctText": "METRO, CTO, NTE, SUR, OCC"}, {"id": 50, "q": "Si la información del Directorio Activo se comparte y se encuentra disponible para todo usuario y equipo, ¿un usuario del dominio Norte (NTE) podría abrir sesión en una computadora migrada al dominio SUR ubicada en el estado de Yucatán?", "opts": ["Falso. Un usuario del dominio Norte debe obtener una cuenta del dominio Sur", "Cierto, pero debería trasladar la máquina hacia el norte del país para tener mejor señal", "Falso", "Cierto, sin problemas"], "correctText": "Cierto, sin problemas"}, {"id": 51, "q": "¿Qué opción hay que configurar para que la PC arranque desde CD?", "opts": ["Configurar BIOS.", "Configurar la Unidad de Diskette.", "Cambiar el cable que va al CD", "Seleccionar inicio, explorador y seleccionar la Unidad C:"], "correctText": "Configurar BIOS."}, {"id": 52, "q": "¿Con qué requerimiento Legal se debe contar para poder instalar cualquier Software en una PC del Instituto?", "opts": ["Con una carta de autorización del C.D.I.", "La clave o Licencia.", "Con una autorización del Órgano Interno de Control.", "Que el CD cuente con una etiqueta donde se registre el nombre de la paquetería que contiene."], "correctText": "La clave o Licencia."}, {"id": 53, "q": "¿Cuál es la finalidad de asignarle un nombre al equipo al cual se le está instalando el Sistema Operativo?", "opts": ["Para que el equipo sea identificado dentro de una Red.", "Que el equipo trabaje más rápido.", "Que el usuario pueda identificar su equipo.", "Encontrar los documentos más rápido dentro de una red."], "correctText": "Para que el equipo sea identificado dentro de una Red."}, {"id": 54, "q": "¿Qué elementos son necesarios para utilizar el Correo Electrónico?", "opts": ["Cuenta o dirección que cuente con código Postal.", "Es un requerimiento indispensable el contar con Red de Banda Ancha.", "Cuenta o dirección de correo electrónico, Acceso a Internet.", "Una Computadora con procesador PIV o superior"], "correctText": "Cuenta o dirección de correo electrónico, Acceso a Internet."}, {"id": 55, "q": "¿Qué puede originar el uso inapropiado de los servicios de Correo Electrónico dentro del Instituto?", "opts": ["Consecuencias de índole legal que sean aplicables a quien incurra en mal uso.", "La aplicación de las sanciones disciplinarias respectivas.", "La cancelación de la Cuenta de Correo.", "Todas las anteriores."], "correctText": "Todas las anteriores."}, {"id": 56, "q": "¿Qué terminación tienen los archivos que contienen toda la información de los usuarios (mail, citas, contactos)?", "opts": ["Terminación .PST", "Terminación .DOC", "Terminación .EXE", "Terminación .TXT"], "correctText": "Terminación .PST"}, {"id": 57, "q": "Las cuentas y contraseñas asignadas a los usuarios deben de ser:", "opts": ["Gratuitas y transferibles.", "Registradas en la bitácora de actividades diarias.", "Deben de contar con caracteres especiales.", "Deben de ser personales e intransferibles."], "correctText": "Deben de ser personales e intransferibles."}, {"id": 58, "q": "¿Cuántos caracteres de longitud mínima debe tener una contraseña?", "opts": ["12 caracteres como mínimo.", "4 caracteres como mínimo.", "6 caracteres como mínimo.", "No cuenta con un mínimo de caracteres."], "correctText": "6 caracteres como mínimo."}, {"id": 59, "q": "Es un documento establecido por consenso y aprobado por un organismo reconocido que establece para usos comunes reglas, criterios o características para las actividades o sus resultados, que procura la obtención de un nivel óptimo de ordenamiento en un contexto determinado:", "opts": ["Un Proceso.", "Una Norma.", "Una Política.", "Nombramiento del trabajador."], "correctText": "Una Norma."}, {"id": 60, "q": "Definición de Checklist:", "opts": ["Listado de procedimientos para la consecución de un objetivo.", "Listado de opciones para llenar datos de control a un formato dado.", "Listado de configuraciones que deben seguirse en el tiempo marcado.", "Procesos de actualización para la rápida referencia."], "correctText": "Listado de procedimientos para la consecución de un objetivo."}, {"id": 61, "q": "Sistema que lleva a cabo procesos relacionados con Afiliación:", "opts": ["Cobranza", "Contabilidad", "Guarderías", "SINDO-APM"], "correctText": "SINDO-APM"}, {"id": 62, "q": "Sistema que lleva a cabo procesos relacionados con Contabilidad:", "opts": ["TG-CO", "PREI", "SINDO-APM", "SN-PG"], "correctText": "PREI"}, {"id": 63, "q": "Sistema que lleva a cabo procesos relacionados con Personal:", "opts": ["SIAP", "DO-ST", "SINDO", "SIVEPA"], "correctText": "SIAP"}];
export const MODULES = [{"id": 1, "icon": "💻", "title": "Introducción a las Microcomputadoras", "explicacion": "Este módulo cubre los conceptos base de una computadora: qué es, sus cuatro funciones (entrada, procesamiento, almacenamiento, salida), y la diferencia entre Hardware (lo físico, tangible) y Software (los programas). También entra el papel del Sistema Operativo como intermediario entre el usuario y el Hardware, y qué es un lenguaje de programación.", "resumen": ["Computadora = dispositivo electrónico que ejecuta comandos programados (entrada, cómputo, lógica, salida).", "Hardware = tangible (lo tocas). Software = programas (no lo tocas).", "Sistema Operativo = intermediario entre usuario y Hardware; administra recursos.", "Medios de almacenamiento comunes: diskette, disco duro, DVD, memoria, cámara digital.", "Un Software necesita Licencia para poder instalarse y usarse legalmente."], "puntos_clave": ["4 funciones de un sistema de cómputo: Entrada → Procesamiento → Almacenamiento → Salida.", "Velocidad de procesador se mide en GHz o MHz.", "Compilador = traduce lenguaje de programación a lenguaje máquina."], "errores_comunes": ["Confundir Hardware (físico) con Software (lógico/programas).", "Pensar que 'Sistema Operativo' y 'Sistema Aplicativo' son lo mismo — el SO es el intermediario base; las aplicaciones corren sobre él."], "mnemotecnia": "HARDware = lo que 'agarras con la mano' (tangible). SOFTware = lo 'suave', intangible, son instrucciones."}, {"id": 2, "icon": "🛠️", "title": "Mantenimiento Preventivo y Correctivo", "explicacion": "El mantenimiento preventivo es el conjunto de acciones periódicas para evitar fallas (limpieza, revisión de conectores, defragmentación, verificación de cables). El correctivo es la reparación una vez que ya existe una falla. Se estudian herramientas (aire comprimido, pulsera antiestática, brochas), enemigos de los equipos (polvo, calor, humedad) y buenas prácticas de limpieza por componente.", "resumen": ["Preventivo = evitar fallas ANTES de que ocurran. Correctivo = reparar DESPUÉS de la falla.", "Enemigos principales: calor y humedad (también polvo, que retiene calor y puede generar cortos).", "Antes de destapar un CPU: apagar y desenergizar el equipo, usar pulsera antiestática.", "Aire comprimido: para retirar polvo. Alcohol isopropílico: para limpiar cabezas de lectura/contactos.", "Backup (copia de seguridad) = respaldo de carpetas y documentos importantes.", "La defragmentación reorganiza los archivos del disco para mejorar el rendimiento."], "puntos_clave": ["Frecuencia típica recomendada: cada 6 meses (varía según el contexto de la pregunta).", "Duración típica de un mantenimiento preventivo: 1 a 6 horas.", "El componente que más polvo retiene: la fuente de poder (por el ventilador que succiona aire).", "El mouse se ensucia por estar en contacto con el escritorio/tapete."], "errores_comunes": ["Limpiar el equipo sin apagarlo y desconectarlo primero — riesgo de descarga o corto.", "Usar agua o líquidos agresivos en vez de alcohol isopropílico o aire comprimido.", "No usar pulsera antiestática al tocar componentes internos."], "mnemotecnia": "PREVENIR es antes (con 'P' de Planeado); CORREGIR es después (ya talló, 'C' de Compostura)."}, {"id": 3, "icon": "🌐", "title": "Introducción a Redes", "explicacion": "Una red es un conjunto de dispositivos, conexiones físicas y programas que permiten a dos o más computadoras comunicarse y compartir recursos. Se estudian los tipos de red (LAN, MAN, WAN), los dispositivos de interconexión (Hub, Switch, Router) y los protocolos fundamentales (IP, HTTP, FTP, DHCP).", "resumen": ["LAN = Red de Área Local. WAN = Red de Área Extensa (grandes distancias). MAN = Red de Área Metropolitana.", "Switch = dispositivo de interconexión que opera en la capa 2 del modelo OSI.", "Router (Ruteador) = crea y mantiene tablas de ruteo, elige la mejor ruta.", "Hub/Concentrador = centraliza el cableado de una red, permite ampliarla (no filtra tráfico como el switch).", "Protocolo más popular del mundo: IP (Protocolo de Internet).", "HTTP = transferencia de hipertexto. FTP = transferencia de archivos. DHCP = asignación dinámica de IP.", "Patch Panel = donde terminan los cables de red y se ubican los puertos."], "puntos_clave": ["Los 5 dominios institucionales del IMSS: METRO, CTO, NTE, SUR, OCC.", "Un usuario de un dominio no puede iniciar sesión directamente en otro dominio sin una cuenta propia de ese dominio.", "Niveles de componentes de una red: Software de aplicaciones, Software de red, Hardware de red."], "errores_comunes": ["Confundir Hub (repite tráfico a todos) con Switch (dirige tráfico de forma inteligente).", "Pensar que LAN y WAN cubren la misma escala geográfica."], "mnemotecnia": "METRO-CTO-NTE-SUR-OCC → 'Mi Ciudad No Se Olvida' (orden de los 5 dominios del Instituto)."}, {"id": 4, "icon": "🔌", "title": "Cableado Estructurado", "explicacion": "El cableado estructurado es el sistema físico (cables, conectores, paneles) que soporta voz, datos y video bajo normas ANSI/TIA/EIA. Incluye tipos de cable (UTP, fibra óptica, coaxial), parámetros de medición (NEXT, FEXT, atenuación) y estándares de instalación (longitudes máximas, colores de pares, categorías).", "resumen": ["Longitud máxima de un enlace horizontal UTP: 90 metros (con 10m adicionales para patch cords = 100m total).", "Norma ANSI/TIA/EIA 568B.1 = cableado en edificios comerciales. 568B.3 = componentes de fibra óptica.", "Colores de pares UTP (T568B): Blanco-Naranja, Blanco-Verde, Blanco-Azul, Blanco-Café, Blanco-Gris.", "NEXT = ruido inducido en un par por una señal de otro par (diafonía) del MISMO extremo.", "Fibra óptica: dieléctrica, no es conductor eléctrico, inmune a interferencia electromagnética.", "Diámetro núcleo fibra multimodo: 62.5 µm o 50 µm; cubierta (cladding): 125 µm.", "Radio de curvatura recomendado para UTP: 4 veces su diámetro."], "puntos_clave": ["T568A vs T568B: cambian de posición los pares blanco-naranja y blanco-verde.", "Punto de Consolidación: permite cambios sin sustituir todo el cable horizontal.", "Cuarto de Telecomunicaciones (TR) vs Cuarto de Equipo: el de equipo es más complejo/crítico."], "errores_comunes": ["Confundir NEXT (mismo extremo) con FEXT (extremo lejano).", "Olvidar que la fibra óptica NO es conductor eléctrico (es dieléctrica).", "Confundir T568A con T568B en el orden de colores."], "mnemotecnia": "90 metros = 'cableado que casi llega a un campo de futbol americano' (90m ≈ campo sin zonas de anotación)."}, {"id": 5, "icon": "🛡️", "title": "Antivirus (McAfee VirusScan / ePO)", "explicacion": "Este módulo cubre el software antivirus institucional McAfee VirusScan 8.5i y el agente ePolicy Orchestrator (ePO), que administra políticas y actualizaciones de forma centralizada. También cubre amenazas comunes: virus, spyware, adware, phishing, hoax y spam.", "resumen": ["ePO Agent: hace inventario de software y aplica políticas/actualizaciones enviadas por el servidor ePO.", "Para desinstalar el agente ePO: FrmInst.exe /remove=agent.", "Para instalar VirusScan 8.5i: Setupvse.exe. Para desinstalarlo: VSE850.MSI.", "Actualización de motor y DAT (definiciones de virus): archivos DAT / SuperDAT / ExtraDAT.", "Phishing = páginas falsas para robar datos. Hoax = correo con falsa alerta. Spam = correo masivo no deseado.", "Spyware = recopila info y la envía a un servidor externo (sin permiso). Adware = muestra publicidad."], "puntos_clave": ["Archivo para ver eventos de detección en tiempo real: OnAccessScanLog.txt.", "Para arrancar en Modo de Fallo/Seguro al iniciar: tecla F8.", "Extensiones de archivo riesgosas a evitar por correo: .exe, .bat, .vbs, .pif, .reg, .scr, .com."], "errores_comunes": ["Confundir Spyware (roba info) con Adware (solo publicidad).", "No diferenciar Hoax (alerta falsa) de un virus real.", "Olvidar el comando exacto de desinstalación del agente ePO."], "mnemotecnia": "ePO = 'el Policía Organizador' — vigila y ordena las políticas de todos los equipos desde un solo lugar."}, {"id": 6, "icon": "🗂️", "title": "Directorio Activo", "explicacion": "Active Directory (Directorio Activo) es el servicio de directorio de Windows Server que centraliza la administración de usuarios, equipos y recursos de una red bajo un dominio. Se estudia el proceso de migración de un equipo a dominio, perfiles de usuario y protocolos asociados (DNS, Kerberos, WINS).", "resumen": ["Active Directory = servicio de directorio de Windows 2000/2003 Server, permite administración centralizada.", "Protocolos usados: DNS, Kerberos V5 y NetBIOS/WINS.", "Dominio = conjunto de equipos que comparten una base de datos de directorio común (identificado por nombre DNS).", "Para migrar un equipo a dominio se necesita: cuenta de administrador local del equipo + cuenta con permiso para agregar equipos al dominio.", "El perfil de usuario en uso se debe copiar DESPUÉS de iniciar sesión por primera vez con la cuenta de dominio (para crear la carpeta del nuevo perfil).", "Los perfiles de usuario en Windows XP/2000 se guardan en: <windrive>\\Documents and Settings."], "puntos_clave": ["En una red con DHCP: la IP, DNS y WINS se configuran de forma AUTOMÁTICA.", "El nombre de equipo debe seguir el estándar institucional: Dominio, Ubicación, Tipo, Iniciales, Consecutivo.", "La información en un dominio está CENTRALIZADA (a diferencia de un grupo de trabajo, donde es distribuida)."], "errores_comunes": ["Creer que un equipo en grupo de trabajo puede administrarse igual que uno en dominio.", "Copiar el perfil ANTES de haber iniciado sesión con la cuenta de dominio por primera vez."], "mnemotecnia": "Directorio Activo = 'el directorio telefónico centralizado' de toda la organización: un solo lugar donde buscar cualquier recurso."}, {"id": 7, "icon": "⚙️", "title": "Instalación y Configuración de PC", "explicacion": "Cubre el proceso de instalar el sistema operativo, configurar el entorno de red (grupo de trabajo o dominio), instalar paquetería con licencia, y las opciones esenciales del Panel de Control (cuentas de usuario, Firewall, actualizaciones automáticas, orígenes de datos ODBC).", "resumen": ["Requisito legal para instalar cualquier software institucional: contar con su Licencia.", "El Firewall de Windows debe estar ACTIVADO para mejor protección.", "El Panel de Control permite configurar todo el entorno de Windows (cuentas, red, actualizaciones, ODBC).", "Windows Update: revisa la configuración del equipo y genera una lista de actualizaciones necesarias.", "Al configurar red típica, el equipo se agrega a un Grupo de trabajo (configuración por defecto antes de migrar a dominio)."], "puntos_clave": ["Ruta para Directiva de Seguridad Local: Panel de Control → Herramientas Administrativas → Directiva de Seguridad Local.", "Ruta para Orígenes de Datos ODBC: Panel de Control → Herramientas Administrativas → Orígenes de Datos ODBC.", "Windows Vista requiere mínimo 800 MHz y 512 MB de RAM (según el estándar de la pregunta institucional)."], "errores_comunes": ["Confundir la ruta de Cuentas de Usuario con la de Directiva de Seguridad Local.", "Dejar el Firewall desactivado pensando que el antivirus es suficiente."], "mnemotecnia": "Panel de Control = 'el tablero de mandos' del equipo: todo se configura desde ahí."}, {"id": 8, "icon": "📧", "title": "Correo y Mensajería Institucional", "explicacion": "Cubre la configuración de Outlook con Microsoft Exchange, el manejo de archivos .PST, y las buenas prácticas/normativa de uso de correo institucional (qué se puede y no se puede enviar).", "resumen": ["Archivo que contiene correo, citas y contactos del usuario: extensión .PST.", "Servidor de correo institucional: Microsoft Exchange (imssexbe01 como ejemplo de servidor).", "Modo de intercambio importante a habilitar en versiones posteriores a Windows 2000: modo caché.", "El uso inapropiado del correo puede derivar en sanciones disciplinarias y consecuencias legales.", "La info Confidencial o Reservada NO debe enviarse a terceros sin autorización, y debe cifrarse."], "puntos_clave": ["Ventajas del correo electrónico: comodidad, velocidad, fiabilidad en la recepción.", "Antes de enviar adjuntos: evitar >2MB y evitar extensiones ejecutables o doble punto en el nombre.", "Todo correo enviado por la infraestructura institucional (incluso personal) es propiedad del Instituto y puede ser monitoreado."], "errores_comunes": ["Pensar que el correo personal enviado desde cuentas institucionales es privado — NO lo es, es propiedad del Instituto.", "Responder o reenviar correos de dudosa procedencia en vez de eliminarlos sin abrir."], "mnemotecnia": "PST = 'Paquete con Todo mi correo' — Personal STorage, guarda absolutamente todo tu buzón."}, {"id": 9, "icon": "📜", "title": "Normatividad y Seguridad Informática (Norma 5000-001-001)", "explicacion": "Es la Norma que establece las disposiciones en materia de Seguridad Informática del IMSS (Clave 5000-001-001). Define responsables (usuarios, administradores, desarrolladores), reglas de uso de infraestructura, contraseñas, clasificación de información (Confidencial/Reservada/Pública), respaldos, seguridad física y desarrollo de sistemas.", "resumen": ["La Norma es de observancia OBLIGATORIA para todo el personal del IMSS y personal externo que use su infraestructura.", "Responsable de difusión y actualización a nivel central: Dirección de Innovación y Desarrollo Tecnológico.", "A nivel Delegacional: la Coordinación Delegacional de Informática vigila el cumplimiento.", "Contraseñas: deben ser personales e intransferibles; cambiar en el primer acceso; longitud mínima de 6 caracteres (norma 7.4.5.11), aunque el estándar de generación pide combinar letras+2 números entre 6 y 8 caracteres (7.2.3.3).", "Las cuentas se bloquean tras 3 intentos fallidos consecutivos.", "Cuenta sin uso 30 días → se bloquea. Sin uso 120 días → se elimina (si no hay causa justificada).", "Cambio forzado de contraseña: cada 60 días máximo, distinta a las últimas 10 usadas.", "Información Confidencial o Reservada debe residir en TERRITORIO NACIONAL."], "puntos_clave": ["3 figuras de la información: Responsables (dueños), Depositarios (áreas técnicas/soporte), Usuarios finales (capturan/explotan).", "El Plan de Contingencias Institucional debe revisarse/probarse periódicamente y tener copia FUERA de las instalaciones.", "Los respaldos con ciclo largo de retención (cintas) se verifican cada 2 años.", "Las violaciones a la Norma pueden causar revocación de accesos + sanciones disciplinarias + consecuencias legales."], "errores_comunes": ["Confundir Responsable (dueño de la info) con Depositario (quien la resguarda técnicamente).", "Olvidar los plazos exactos: 3 intentos fallidos, 30 días bloqueo, 60 días cambio de contraseña, 120 días eliminación de cuenta.", "Pensar que la info Confidencial puede alojarse en servidores fuera de México — NO, debe estar en territorio nacional."], "mnemotecnia": "3-30-60-120: 'Tres fallos te bloquean, 30 días te congelan, 60 días cambias clave, 120 días te borran.'"}, {"id": 10, "icon": "🏢", "title": "Actualizaciones de Sistemas Institucionales", "explicacion": "Cubre las herramientas propias del IMSS para gestión de instrucciones normativas y descarga de archivos (SeTrar, CNTI, SAPRODEL), el uso de Microsoft Project para gestión de proyectos, los sistemas institucionales por proceso (SIAP, PREI, SINDO-APM, TG-CO) y procesos de producción (impresión, ensobretado, respaldos).", "resumen": ["SIAP = Sistema relacionado con procesos de Personal.", "TG-CO = Sistema relacionado con procesos de Contabilidad.", "SINDO-APM = Sistema relacionado con procesos de Afiliación.", "SeTrar = herramienta Web para dar seguimiento a instrucciones normativas y descargar archivos.", "Microsoft Project sirve para administrar tareas asignándoles tiempos y dar seguimiento a su avance.", "Vistas de Project: Gantt, de Red, Calendario.", "Un Checklist debe tener: Encabezado, datos de llenado y Pie; sus opciones deben ser lo más acotadas posible."], "puntos_clave": ["Un proceso es medible, entrega resultados y responde a eventos (se puede reconocer por esas 3 características).", "Los sistemas de producción generan procesos periódicos (diario, semanal, mensual) y algunos a petición del usuario.", "El ensobretado ocurre en la emisión mensual anticipada; al terminar, se debe limpiar el equipo de ensobretado."], "errores_comunes": ["Confundir los acrónimos de sistemas institucionales entre sí (SIAP vs PREI vs TG-CO vs SINDO-APM).", "No reconocer las 3 pestañas típicas de datos de una tarea en Project: General, Predecesoras, Recursos, Avanzado."], "mnemotecnia": "SIAP suena a 'Sí, A Personal' (Sistema de personAl). TG-CO suena a 'ConTabilidad-CO'."}];
